def build_agent(sandbox):
    # Main buoyant structure with wide base for stability
    main_beam = sandbox.add_beam(x=5.0, y=1.5, width=3.0, height=0.5, density=10.0)
    sandbox.set_material_properties(main_beam, restitution=0.05)
    return main_beam

def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body.active:
        return

    front_x = sandbox.get_vehicle_front_x() or agent_body.position.x
    target_x = 26.0

    if front_x >= target_x + 0.1:
        # Reached target, apply controlled deceleration
        for b in sandbox.bodies:
            if b.active:
                sandbox.apply_force(b, -200.0, 0.0, step_count=step_count)
        return

    # Apply thrust every 3 steps (cooldown)
    if step_count % 3 == 0:
        THRUST_F = 520.0  # Maximum allowed thrust per step
        in_danger_zone = (12.0 <= front_x <= 22.0)  # Deep channel range

        # Apply force to the main body
        sandbox.apply_force(agent_body, THRUST_F, 0.0, step_count=step_count)

        # Apply upward force in deep channel to counteract reduced buoyancy
        if in_danger_zone:
            sandbox.apply_force(agent_body, 0.0, 300.0, step_count=step_count)
